/**
 * Validate and deduplicate waitlist emails
 * Simple: all waitlist patients get notified
 */

const waitlistPatients = $input.all();

console.log(`🔍 DEBUG: Received ${waitlistPatients.length} patients from Read Waitlist`);

if (waitlistPatients.length === 0) {
  console.log('ℹ️ No patients on waitlist');
  return [];
}

// DEBUG: Log first patient structure to see column names
if (waitlistPatients.length > 0) {
  console.log('🔍 DEBUG: First patient data:', JSON.stringify(waitlistPatients[0].json, null, 2));
}

const validated = [];
const emailSet = new Set(); // Deduplicate emails

for (const item of waitlistPatients) {
  try {
    const patient = item.json;

    // Try multiple possible email field names
    const email = patient["Patient_Email"] || 
                  patient["Email Address"] || 
                  patient["Email"] || 
                  patient["email"] ||
                  patient["patient_email"];

    const name = patient["Patient_Name"] || 
                 patient["Full_Name"] || 
                 patient["Full Name"] ||
                 patient["Name"] ||
                 patient["name"] ||
                 "Unknown";

    console.log(`🔍 DEBUG: Processing patient: ${name}, email: ${email}`);

    // Skip if no email
    if (!email) {
      console.warn(`⚠️ Waitlist patient has no email: ${name}`);
      continue;
    }

    // Skip duplicates
    if (emailSet.has(email)) {
      console.log(`⚠️ Duplicate email skipped: ${email}`);
      continue;
    }

    validated.push(item);
    emailSet.add(email);
    console.log(`✅ Added ${name} (${email})`);

  } catch (error) {
    console.error(`❌ Error processing waitlist patient:`, error.message);
  }
}

console.log(`
📊 Waitlist Summary:
  - Total on waitlist: ${waitlistPatients.length}
  - Valid unique emails: ${validated.length}
`);

return validated;

/**
 * Prepare mass email with Cal.com booking link
 * Format: https://cal.com/izzydevbuilds/appointment-with-dr.-jennifer?slot=2025-10-31T09:00:00.000Z
 */

const webhookData = $('Webhook Trigger').first().json.body;
const waitlistPatients = $input.all();

// DEBUG: Log what we received from the webhook
console.log('🔍 DEBUG: Webhook data received:', JSON.stringify(webhookData, null, 2));

// Extract all emails for BCC (using correct field name from your Google Sheet)
const emails = waitlistPatients.map(p => p.json["Email Address"]).filter(Boolean);

// Parse date and time to ISO format
const dateStr = webhookData.appointmentDate; // "2025-10-31"
const timeStr = webhookData.appointmentTime; // "3:45 PM"
const doctorName = webhookData.doctorName;
const appointmentType = webhookData.appointmentType;
const reason = webhookData.reason || "cancelled";

console.log(`🔍 DEBUG: Extracted values - Date: ${dateStr}, Time: ${timeStr}, Doctor: ${doctorName}, Type: ${appointmentType}`);

const reasonText = reason === "rescheduled" 
  ? "has been RESCHEDULED and this slot" 
  : "has been CANCELLED and this slot";

// Convert to ISO format for Cal.com slot parameter
let slotISO = "";
try {
  const dateTimeStr = `${dateStr} ${timeStr}`;
  const dateObj = new Date(dateTimeStr);
  slotISO = dateObj.toISOString(); // "2025-10-31T15:45:00.000Z"
} catch (error) {
  console.error(`Error parsing date/time: ${error.message}`);
  slotISO = ""; // Fallback to no pre-fill
}

// Build Cal.com booking URL
const calcomBaseUrl = "https://cal.com/izzydevbuilds/appointment-with-dr.-jennifer";
const calcomBookingUrl = slotISO 
  ? `${calcomBaseUrl}?slot=${encodeURIComponent(slotISO)}`
  : calcomBaseUrl; // Fallback to generic URL if parsing fails

console.log(`📅 Cal.com booking URL: ${calcomBookingUrl}`);

return [{
  json: {
    bccEmails: emails.join(", "),
    slotDate: dateStr,
    slotTime: timeStr,
    slotDoctor: doctorName,
    slotType: appointmentType,
    reasonText: reasonText,
    waitlistCount: emails.length,
    calcomBookingUrl: calcomBookingUrl,
    webhookData: webhookData
  }
}];

